-- Tags: no-fasttest
-- no-fasttest: requires the ORC input format, which is not built in fasttest.

SET allow_experimental_variant_type = 1;

-- ORC uniontype<struct<a:uniontype<int,int>,b:string>,string>: the struct branch's field `a` is
-- itself an ORC union with two identical-type branches, which the native ORC reader always
-- rejects once it is actually inspected (see 04602_orc_native_union_nested for the closely
-- related "nested union" rejection). Rows: struct{a=10,b='x'}, string 'hello', struct{a=20,b='y'}.

-- Schema inference always inspects every field of every branch, so it hits the unsupported `a`
-- and fails, the same as reading with an explicit schema that references `a`.
DESC format(ORC, unhex('')); -- { serverError CANNOT_EXTRACT_TABLE_STRUCTURE }

-- An explicit schema that references `a` forces the reader to inspect it too, and fails the same way.
SELECT u FROM format(ORC, $$u Variant(Tuple(a String, b String), String)$$, unhex('')); -- { serverError UNKNOWN_TYPE }

-- An explicit schema that projects the struct branch down to just `b` must never inspect `a` at
-- all: the union branch's include-set computation must recurse into the same per-branch type hint
-- the read path uses, so a hinted STRUCT branch only selects the fields the hint's tuple actually
-- references, exactly like the ordinary (non-union) ORC struct-pruning path already does.
SELECT u FROM format(ORC, $$u Variant(Tuple(b String), String)$$, unhex('')) ORDER BY toString(u);
